CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE staff_users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','CONSULTANT')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE travel_packages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug VARCHAR(180) UNIQUE NOT NULL, title VARCHAR(200) NOT NULL, destination VARCHAR(160) NOT NULL, region VARCHAR(160), summary VARCHAR(800), description TEXT, cover_image_url TEXT, duration_nights INT NOT NULL CHECK(duration_nights > 0), hotel_category VARCHAR(120), starting_price NUMERIC(12,2) NOT NULL CHECK(starting_price >= 0), inclusions TEXT, exclusions TEXT, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')), version INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE package_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), package_id UUID NOT NULL REFERENCES travel_packages(id) ON DELETE CASCADE, version INT NOT NULL, snapshot JSONB NOT NULL, editor_email VARCHAR(254) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(package_id,version));
CREATE TABLE seasonal_prices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), package_id UUID NOT NULL REFERENCES travel_packages(id) ON DELETE CASCADE, label VARCHAR(100) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, price NUMERIC(12,2) NOT NULL CHECK(price >= 0), CHECK(ends_on >= starts_on));
CREATE TABLE itinerary_days(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), package_id UUID NOT NULL REFERENCES travel_packages(id) ON DELETE CASCADE, day_number INT NOT NULL CHECK(day_number > 0), title VARCHAR(200) NOT NULL, description TEXT NOT NULL, UNIQUE(package_id,day_number));
CREATE TABLE enquiries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key VARCHAR(100) UNIQUE, package_id UUID REFERENCES travel_packages(id) ON DELETE SET NULL, full_name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(30) NOT NULL, destination VARCHAR(160) NOT NULL, travel_date DATE NOT NULL, adults INT NOT NULL CHECK(adults > 0), children INT NOT NULL DEFAULT 0 CHECK(children >= 0), budget NUMERIC(12,2) CHECK(budget >= 0), message VARCHAR(3000), whatsapp_consent BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(24) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','CONTACTED','QUALIFIED','QUOTED','CONVERTED','CLOSED')), ai_status VARCHAR(24) NOT NULL DEFAULT 'PENDING', ai_summary TEXT, ai_extraction JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX enquiries_status_created_idx ON enquiries(status,created_at DESC); CREATE INDEX packages_public_idx ON travel_packages(status, destination); CREATE INDEX versions_package_idx ON package_versions(package_id,version DESC);
INSERT INTO travel_packages(slug,title,destination,region,summary,description,cover_image_url,duration_nights,hotel_category,starting_price,inclusions,exclusions,status) VALUES
('munnar-thekkady-alleppey','Munnar, Thekkady & Alleppey','Munnar · Thekkady · Alleppey','Kerala','Tea country mornings, forest trails and a night on the backwaters.','A considered journey from the misty highlands of Munnar through Thekkady and on to a private houseboat in Alleppey.','https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=1200&q=80',6,'Boutique 4-star stays',42500,'Accommodation, breakfast, private transfers, houseboat stay','Flights, lunch and dinner unless specified','PUBLISHED'),
('wayanad-slow-trails','Wayanad, at your own pace','Wayanad','Kerala','Forest stays, spice gardens and generous time to simply be.','A slow escape into the green heart of Wayanad, with a private naturalist and a restful forest-side stay.','https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1200&q=80',4,'Forest retreat',31800,'Accommodation, breakfast, private transfers','Flights, meals not specified','PUBLISHED'),
('kochi-munnar-escape','Kochi to the hills','Kochi · Munnar','Kerala','A gentle city-to-mountain escape with time to wander.','Start among Fort Kochi lanes before climbing into Munnar’s tea gardens.','https://images.unsplash.com/photo-1562649846-55dd9b82622d?auto=format&fit=crop&w=1200&q=80',5,'Handpicked 4-star stays',36200,'Accommodation, breakfast, private transfers','Flights, personal expenses','PUBLISHED');
INSERT INTO itinerary_days(package_id,day_number,title,description) SELECT id,1,'Arrive in Kerala','Meet your private driver and settle into your first stay.' FROM travel_packages WHERE slug='munnar-thekkady-alleppey';
INSERT INTO travel_packages(slug,title,destination,region,summary,description,cover_image_url,duration_nights,hotel_category,starting_price,inclusions,exclusions,status) VALUES
('alappuzha-backwater-retreat','Alappuzha backwater retreat','Alappuzha','Kerala','A gentle escape of canals, coconut groves and unhurried houseboat evenings.','Spend three unhurried nights around Alappuzha, with a private backwater cruise, a heritage stay and generous time to follow the water at your own pace.','https://images.unsplash.com/photo-1602301414682-03f4fc2f3c3f?auto=format&fit=crop&w=1400&q=85',3,'Heritage waterside stay',28600,'Accommodation, daily breakfast, private transfers and a sunset backwater cruise','Flights, lunch and dinner unless specified','PUBLISHED');
UPDATE travel_packages SET cover_image_url=CASE slug
  WHEN 'munnar-thekkady-alleppey' THEN 'https://unsplash.com/photos/PHOk0ZP28a0/download?force=true&w=1400'
  WHEN 'wayanad-slow-trails' THEN 'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1400&q=85'
  WHEN 'kochi-munnar-escape' THEN 'https://unsplash.com/photos/d6ar7QaEDTs/download?force=true&w=1400'
  WHEN 'alappuzha-backwater-retreat' THEN 'https://unsplash.com/photos/qRYVfsTKTOE/download?force=true&w=1400'
  ELSE cover_image_url
END;
 
